import {pool} from '../repositories/db.js';import {sha256Json} from '../core/hash.js';
const run=process.argv[2],cert=process.argv[3];if(!run||!cert)throw new Error('USAGE: activate <normalization_run_uuid> <certification_run_uuid>');
const p=pool(),c=await p.connect();try{await c.query('begin');const ev={reason:'EXPLICIT_PRODUCTION_AUTHORITY_ACTIVATION',actor:process.env.ZSL2_ACTOR_ID??'zsl2-certifier',run,cert};const q=await c.query(`select zsl.zsl2_activate($1,$2,$3,$4,$5::jsonb,$6)::text authority_event_id`,[run,cert,ev.actor,ev.reason,JSON.stringify(ev),sha256Json(ev)]);await c.query('commit');console.log(JSON.stringify({authorityEventId:q.rows[0].authority_event_id,status:'ACTIVATED'}));}catch(e){await c.query('rollback');throw e}finally{c.release();await p.end()}
